WITH recent_stores AS (SELECT *, UPPER(TRIM(store_name)) AS store_name_normalized FROM stores WHERE region IS NULL), summary AS (SELECT region, CASE WHEN region IN ('Central', 'West') THEN 'core' ELSE 'other' END AS region_group, MAX(opened_date) AS last_opened_date, ROUND((100 * SUM(CASE WHEN city = 'New York' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_new_york FROM recent_stores GROUP BY region, CASE WHEN region IN ('Central', 'West') THEN 'core' ELSE 'other' END) SELECT region, region_group, last_opened_date, pct_new_york FROM summary WHERE pct_new_york >= 48
